<?php
namespace App\Http\Controllers;
use App\Models\Examination;
use App\Models\ExaminationMark;
use App\Models\AttendanceRecord;
use App\Models\Student;
use App\Models\ExaminationAttendance;
use App\Services\PermissionService;
use App\Services\AuditLogger;
use App\Support\BranchContext;
use App\Support\OrganizationContext;
use Illuminate\Http\JsonResponse;
use Illuminate\Http\Request;
use Illuminate\Support\Str;
use Illuminate\Validation\Rule;
use Illuminate\Support\Facades\DB;
class ExaminationController extends Controller {
 public function index(Request $request, BranchContext $branches, PermissionService $permissions): JsonResponse { abort_unless($permissions->has($request->attributes->get('membership'),'view_reports'),403); $exams=Examination::where('branch_id',$branches->get()->id)->with(['subject:id,name_ar,name_en,code','groups:id,name_ar,name_en,code'])->withCount('marks')->latest('exam_date')->latest()->get(); return response()->json(['exams'=>$exams]); }
 public function store(Request $request, OrganizationContext $organizations, BranchContext $branches, PermissionService $permissions, AuditLogger $audit): JsonResponse { abort_unless($permissions->has($request->attributes->get('membership'),'create_examinations'),403); $branch=$branches->get(); $data=$request->validate(['title'=>['required','string','max:160'],'subject_id'=>['nullable',Rule::exists('subjects','id')->where('branch_id',$branch->id)],'exam_date'=>['required','date'],'total_marks'=>['required','integer','min:1','max:10000'],'notes'=>['nullable','string','max:2000'],'teaching_group_ids'=>['nullable','array'],'teaching_group_ids.*'=>['integer',Rule::exists('teaching_groups','id')->where('branch_id',$branch->id)]]); $groupIds=$data['teaching_group_ids']??[]; unset($data['teaching_group_ids']); $exam=DB::transaction(function() use($data,$groupIds,$organizations,$branch,$request){$exam=Examination::create([...$data,'organization_id'=>$organizations->id(),'branch_id'=>$branch->id,'public_id'=>(string)Str::ulid(),'created_by'=>$request->user()->id,'status'=>'draft']);if($groupIds)$exam->groups()->sync($groupIds);return $exam;}); $audit->log($request,'examination.created',$exam,[],['title'=>$exam->title,'exam_date'=>$exam->exam_date->toDateString(),'teaching_group_ids'=>$groupIds],$branch->id); return response()->json(['exam'=>$exam->load(['subject:id,name_ar,name_en,code','groups:id,name_ar,name_en,code'])],201); }
 public function marks(int $examId, Request $request, BranchContext $branches, PermissionService $permissions): JsonResponse { abort_unless($permissions->has($request->attributes->get('membership'),'enter_marks'),403); $exam=Examination::where('branch_id',$branches->get()->id)->whereKey($examId)->with('marks.student:id,student_code,name_ar,name_en')->firstOrFail(); $students=$exam->groups()->with('students:id,student_code,name_ar,name_en')->get()->flatMap->students->unique('id')->values(); return response()->json(['exam'=>$exam,'students'=>$students,'marks'=>$exam->marks]); }
 public function saveMarks(int $examId, Request $request, BranchContext $branches, PermissionService $permissions): JsonResponse { abort_unless($permissions->has($request->attributes->get('membership'),'enter_marks'),403); $exam=Examination::where('branch_id',$branches->get()->id)->whereKey($examId)->firstOrFail(); abort_if($exam->status==='locked',422,'Locked exams cannot be changed.'); $data=$request->validate(['marks'=>['required','array','max:2000'],'marks.*.student_id'=>['required','integer'],'marks.*.mark'=>['nullable','numeric','min:0','max:'.$exam->total_marks],'marks.*.comment'=>['nullable','string','max:500']]); $eligible=$exam->groups()->with('students:id')->get()->flatMap->students->pluck('id')->unique(); abort_if(collect($data['marks'])->pluck('student_id')->diff($eligible)->isNotEmpty(),422,'One or more students are not targeted by this exam.'); foreach($data['marks'] as $item){$exam->marks()->updateOrCreate(['student_id'=>$item['student_id']],['entered_by'=>$request->user()->id,'mark'=>$item['mark']??null,'comment'=>$item['comment']??null]);} return response()->json(['updated'=>count($data['marks'])]); }
 public function status(int $examId, Request $request, BranchContext $branches, PermissionService $permissions, AuditLogger $audit): JsonResponse { abort_unless($permissions->has($request->attributes->get('membership'),'publish_results'),403); $exam=Examination::where('branch_id',$branches->get()->id)->whereKey($examId)->firstOrFail(); $data=$request->validate(['status'=>['required',Rule::in(['published','locked'])]]); $next=$data['status']; abort_if($exam->status==='locked',422,'Locked exams cannot be changed.'); abort_if($next==='locked' && $exam->status!=='published',422,'Publish the exam before locking it.'); $previous=$exam->status; $exam->update(['status'=>$next]); $audit->log($request,'examination.status_changed',$exam,['status'=>$previous],['status'=>$next],$exam->branch_id); return response()->json(['exam'=>$exam->fresh()->load(['subject:id,name_ar,name_en,code'])->loadCount('marks')]); }
 public function performance(Request $request, BranchContext $branches, PermissionService $permissions): JsonResponse { abort_unless($permissions->has($request->attributes->get('membership'),'view_reports'),403); $branch=$branches->get(); $marks=ExaminationMark::with(['examination:id,title,total_marks,subject_id','examination.subject:id,name_ar,name_en,code','student:id,student_code,name_ar,name_en'])->whereHas('examination',fn($q)=>$q->where('branch_id',$branch->id)->whereIn('status',['published','locked']))->get(); $examStats=$marks->groupBy('examination_id')->map(function($rows){$exam=$rows->first()->examination;$average=$rows->avg(fn($row)=>$exam->total_marks>0?((float)$row->mark/$exam->total_marks)*100:0);return ['id'=>$exam->id,'title'=>$exam->title,'average'=>round($average,1),'marks_count'=>$rows->count(),'total_marks'=>$exam->total_marks];})->values(); $subjectStats=$marks->filter(fn($row)=>$row->examination->subject)->groupBy(fn($row)=>$row->examination->subject_id)->map(function($rows){$subject=$rows->first()->examination->subject;$average=$rows->avg(fn($row)=>$row->examination->total_marks>0?((float)$row->mark/$row->examination->total_marks)*100:0);return ['id'=>$subject->id,'subject'=>$subject->only(['name_ar','name_en','code']),'average'=>round($average,1),'marks_count'=>$rows->count()];})->sortByDesc('average')->values(); $classAverage=round($marks->avg(fn($row)=>$row->examination->total_marks>0?((float)$row->mark/$row->examination->total_marks)*100:0)??0,1); $attendance=AttendanceRecord::whereHas('session',fn($q)=>$q->where('branch_id',$branch->id))->get()->groupBy('student_id'); $students=Student::where('branch_id',$branch->id)->where('status','active')->get(['id','student_code','name_ar','name_en']); $atRisk=$students->map(function($student)use($marks,$attendance){$studentMarks=$marks->where('student_id',$student->id);$average=$studentMarks->count()?(float)$studentMarks->avg(fn($row)=>$row->examination->total_marks>0?((float)$row->mark/$row->examination->total_marks)*100:0):null;$records=$attendance->get($student->id,collect());$attendanceRate=$records->count()?(($records->whereIn('status',['present','late'])->count()/$records->count())*100):null;$reasons=[];if($average!==null&&$average<60)$reasons[]='low_exam_average';if($attendanceRate!==null&&$attendanceRate<80)$reasons[]='attendance_risk';return $reasons?['student'=>['student_code'=>$student->student_code,'name_ar'=>$student->name_ar,'name_en'=>$student->name_en],'exam_average'=>$average===null?null:round($average,1),'attendance_rate'=>$attendanceRate===null?null:round($attendanceRate,1),'reasons'=>$reasons]:null;})->filter()->values(); return response()->json(['summary'=>['class_average'=>$classAverage,'published_exams'=>$examStats->count(),'students_at_risk'=>$atRisk->count()],'exam_stats'=>$examStats,'subject_stats'=>$subjectStats,'at_risk'=>$atRisk]); }
 public function importMarks(int $examId, Request $request, BranchContext $branches, PermissionService $permissions): JsonResponse { abort_unless($permissions->has($request->attributes->get('membership'),'enter_marks'),403); $exam=Examination::where('branch_id',$branches->get()->id)->whereKey($examId)->firstOrFail(); abort_if($exam->status==='locked',422,'Locked exams cannot be changed.'); $request->validate(['file'=>['required','file','mimes:csv,txt','max:2048']]); $eligible=$exam->groups()->with('students:id,student_code')->get()->flatMap->students->keyBy('student_code'); $handle=fopen($request->file('file')->getRealPath(),'r'); $header=array_map(fn($value)=>strtolower(trim((string)$value)),fgetcsv($handle)?:[]); $required=['student_code','mark']; abort_unless(!array_diff($required,$header),422,'CSV must include student_code and mark columns.'); $index=array_flip($header); $imported=0;$errors=[];$rowNumber=1; while(($row=fgetcsv($handle))!==false&&$rowNumber<=1001){$rowNumber++;$code=trim((string)($row[$index['student_code']]??''));$mark=$row[$index['mark']]??null;$comment=$index['comment']??null?trim((string)($row[$index['comment']]??'')):null;if(!$code||!$eligible->has($code)){$errors[]=['row'=>$rowNumber,'message'=>'Student code is not targeted by this exam.'];continue;}if($mark===''||!is_numeric($mark)||(float)$mark<0||(float)$mark>$exam->total_marks){$errors[]=['row'=>$rowNumber,'message'=>'Mark must be between 0 and '.$exam->total_marks.'.'];continue;}$exam->marks()->updateOrCreate(['student_id'=>$eligible[$code]->id],['entered_by'=>$request->user()->id,'mark'=>(float)$mark,'comment'=>$comment]);$imported++;} fclose($handle); return response()->json(['imported'=>$imported,'errors'=>$errors,'processed'=>$rowNumber-1]); }
 public function attendance(int $examId, Request $request, BranchContext $branches, PermissionService $permissions): JsonResponse { abort_unless($permissions->has($request->attributes->get('membership'),'view_attendance'),403); $exam=Examination::where('branch_id',$branches->get()->id)->whereKey($examId)->firstOrFail(); $students=$exam->groups()->with('students:id,student_code,name_ar,name_en')->get()->flatMap->students->unique('id')->values(); $records=ExaminationAttendance::where('examination_id',$exam->id)->get()->keyBy('student_id'); return response()->json(['exam'=>$exam,'students'=>$students,'attendance'=>$records->values(),'summary'=>['present'=>$records->whereIn('status',['present','late'])->count(),'late'=>$records->where('status','late')->count(),'excused'=>$records->where('status','excused')->count(),'absent'=>$records->where('status','absent')->count()]]); }
 public function saveAttendance(int $examId, Request $request, BranchContext $branches, PermissionService $permissions): JsonResponse { abort_unless($permissions->has($request->attributes->get('membership'),'record_attendance'),403); $branch=$branches->get(); $exam=Examination::where('branch_id',$branch->id)->whereKey($examId)->firstOrFail(); abort_if($exam->status==='locked',422,'Locked exams cannot be changed.'); $data=$request->validate(['attendance'=>['required','array','max:2000'],'attendance.*.student_id'=>['required','integer'],'attendance.*.status'=>['required',Rule::in(['present','late','excused','absent'])]]); $eligible=$exam->groups()->with('students:id')->get()->flatMap->students->pluck('id')->unique(); abort_if(collect($data['attendance'])->pluck('student_id')->diff($eligible)->isNotEmpty(),422,'One or more students are not targeted by this exam.'); foreach($data['attendance'] as $item){ExaminationAttendance::updateOrCreate(['examination_id'=>$exam->id,'student_id'=>$item['student_id']],['organization_id'=>$exam->organization_id,'branch_id'=>$branch->id,'recorded_by'=>$request->user()->id,'status'=>$item['status'],'recorded_at'=>now()]);} return response()->json(['updated'=>count($data['attendance'])]); }
}
